namespace Fanex.Age.UI.TotalBets
{

    public partial class OddEven1x2_Page : TotalBets_Page
    {

        #region Override

        public override void RenderContent(HtmlTextWriter writer)
        {
            DataTable oddEventOneXTwo = View as DataTable;

            OddEven1X2_Template tpl = new OddEven1X2_Template();
            tpl.Contents.LeagueContents.Clear();

            if (oddEventOneXTwo.Rows.Count > 0)
            {
                tpl.Contents.NotFoundContent.Hide();

                // Render league content
                int currentLeagueId = 0;
                int matchIndex = 0;
                OddEven1X2_Contents_LeagueContents_Block leagueBlock = new OddEven1X2_Contents_LeagueContents_Block();
                for (int i = 0; i < oddEventOneXTwo.Rows.Count; i++)
                {
                    DataRow dr = oddEventOneXTwo.Rows[i];

                    int leagueId = Convert.ToInt32(dr["leagueid"]);

                    if (i == 0 || currentLeagueId != leagueId)
                    {
                        // New league, ignore first row
                        if (i != 0) tpl.Contents.LeagueContents.Append(leagueBlock);

                        matchIndex = 1;
                        currentLeagueId = leagueId;

                        leagueBlock.MatchContents.Clear();
                        leagueBlock.LeagueName = Sunplus.Agent.Model.BL.Cache.CacheRef.GetLeagueName(leagueId);
                    }
                    else
                    {
                        matchIndex++;
                    }

                    OddEven1X2_Contents_LeagueContents_MatchContents_Block matchBlock = new OddEven1X2_Contents_LeagueContents_MatchContents_Block();
                    RenderMatchRow(matchBlock, dr, matchIndex, i + 1);

                    leagueBlock.MatchContents.Append(matchBlock);
                }

                if (leagueBlock != null) tpl.Contents.LeagueContents.Append(leagueBlock);
            }

            if (_fullMode)
            {
                writer.Write(tpl);
            }
            else
            {
                writer.Write(tpl.Contents);
            }   
        }
        
        public override object ValidateRequest(System.Collections.Hashtable p)
        {
            return null;
        }

        public override object InvokeData(System.Collections.Hashtable p)
        {
            return _TotalBetsBO.GetOddEventOneXTwo();
        }
        #endregion

        #region Utility

        /// <summary>
        /// Render match row
        /// </summary>
        /// <param name="matchBlock"></param>
        /// <param name="dr"></param>
        /// <param name="matchIndex"></param>
        /// <param name="rowIndex"></param>
        private void RenderMatchRow(OddEven1X2_Contents_LeagueContents_MatchContents_Block matchBlock, DataRow dr, int matchIndex, int rowIndex)
        {
            // Render match content
            // Row Color  and time value
            if (Convert.ToInt16(dr["liveindicator"]) == 1)
            {
                matchBlock.ColorClass = Fanex.Age.UI.Common.RowBgLive;
                matchBlock.TimeValue = dr["livehomescore"] + " - " + dr["liveawayscore"];
                matchBlock.LiveNotice.Show();
            }
            else
            {
                if (dr.Table.Columns.Contains("closed") && Convert.ToInt32(dr["closed"]) != 0)
                {
                    matchBlock.ColorClass = Fanex.Age.UI.Common.RowBgClosed;
                }
                else
                {
                    matchBlock.ColorClass = (matchIndex % 2) == 0 ? Fanex.Age.UI.Common.RowBgEven : Fanex.Age.UI.Common.RowBgOdd;
                }

                matchBlock.TimeValue = dr["showtime"].ToString();
                matchBlock.LiveNotice.Hide();
            }
            matchBlock.ColorOver = Fanex.Age.UI.Common.RowBgOver;

            // Event 
            matchBlock.Home = Sunplus.Agent.Model.BL.Cache.CacheRef.GetTeamName(dr["homeid"]) + (Convert.ToBoolean(dr["isNeutral"]) ? Resources.Lang.IsNeutral : string.Empty);
            matchBlock.Away = Sunplus.Agent.Model.BL.Cache.CacheRef.GetTeamName(dr["awayid"]);
            matchBlock.No = rowIndex.ToString();

            // Render value column
            RenderOddEvenTotal(matchBlock, dr);
            RenderOneXTwoTotal(matchBlock, dr);
            RenderDNDTotal(matchBlock, dr);
            RenderOddEvenFirstHalf(matchBlock, dr);
            RenderOneXTwoFirstHalf(matchBlock, dr);
        }

        /// <summary>
        /// Render odd event total column
        /// </summary>
        /// <param name="matchBlock"></param>
        /// <param name="dr"></param>
        private void RenderOddEvenTotal(OddEven1X2_Contents_LeagueContents_MatchContents_Block matchBlock, DataRow dr)
        {
            //Odd-Even Total
            if (Convert.ToInt16(dr["betcount_oe"]) != 0)
            {
                decimal OETotal = (decimal)(dr["home_odds_OE"]) - (decimal)(dr["away_odds_OE"]);
                matchBlock.OddEvenValue.OddEvenValue = NegativeNumberRoundColor(OETotal);
                matchBlock.OddEvenValue.MatchId = dr["matchid"].ToString();
                matchBlock.OddEvenValue.BetType = Fanex.Age.UI.Common.BetListByBetTypeMatch;
                matchBlock.OddEvenValue.Show();
            }
            else
            {
                matchBlock.OddEvenValue.Hide();
            }
        }

        /// <summary>
        /// Render one x two under total column
        /// </summary>
        /// <param name="matchBlock"></param>
        /// <param name="dr"></param>
        private void RenderOneXTwoTotal(OddEven1X2_Contents_LeagueContents_MatchContents_Block matchBlock, DataRow dr)
        {
            // OneXTwo Total
            if (Convert.ToInt16(dr["betcount_1x2"]) != 0)
            {
                decimal OneXTwoTotal = (decimal)(dr["odds_1"]) + (decimal)(dr["odds_x"]) + (decimal)(dr["odds_2"]);
                matchBlock.OneXTwoValue.OneXTwoValue = Formater.DecFormat(OneXTwoTotal, 0);
                matchBlock.OneXTwoValue.MatchId = dr["matchid"].ToString();
                matchBlock.OneXTwoButton.MatchId = dr["matchid"].ToString();
                matchBlock.OneXTwoValue.BetType = Fanex.Age.UI.Common.BetListByBetTypeMatch;

                matchBlock.OneXTwoValue.Show();
                matchBlock.OneXTwoButton.Show();
            }
            else
            {
                matchBlock.OneXTwoValue.Hide();
                matchBlock.OneXTwoButton.Hide();
            }
        }
