        /// <summary>
        /// Render one x two under first half column
        /// </summary>
        /// <param name="matchBlock"></param>
        /// <param name="dr"></param>
        private void RenderOneXTwoFirstHalf(OddEven1X2_Contents_LeagueContents_MatchContents_Block matchBlock, DataRow dr)
        {
            // OneXTwo First Half
            if (Convert.ToInt16(dr["betcount_1x2_1st"]) != 0)
