                matchBlock.OneXTwoFirstHalfValue.OneXTwoFirstHalfValue = Formater.DecFormat(OneXTwoFirstHalf, 0);
                matchBlock.OneXTwoFirstHalfValue.MatchId = dr["matchid"].ToString();
